package com.kuilunfuzhe.monvhua.gui.commandpanel;
import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.Screen; import net.minecraft.client.gui.widget.ButtonWidget; import net.minecraft.client.gui.widget.TextFieldWidget; import net.minecraft.text.Text;
public final class CommandPopupEditScreen extends Screen { private final CommandPanelScreen parent; private final CommandPanelScreen.Popup popup; private TextFieldWidget nameField, commandField; public CommandPopupEditScreen(CommandPanelScreen p, CommandPanelScreen.Popup popup){super(Text.literal("Edit Popup"));parent=p;this.popup=popup;} @Override protected void init(){nameField=new TextFieldWidget(textRenderer,width/2-150,height/2-45,300,20,Text.literal("Name"));nameField.setText(popup.name);commandField=new TextFieldWidget(textRenderer,width/2-150,height/2-10,300,20,Text.literal("Command"));commandField.setText(popup.command);addDrawableChild(nameField);addDrawableChild(commandField);addDrawableChild(ButtonWidget.builder(Text.literal("Save"),b->{popup.name=nameField.getText();popup.command=commandField.getText();parent.savePanel();client.setScreen(parent);}).dimensions(width/2-50,height/2+25,100,20).build());setInitialFocus(nameField);} @Override public void render(DrawContext c,int x,int y,float d){c.fill(0,0,width,height,0xCC101014);c.drawCenteredTextWithShadow(textRenderer,title,width/2,height/2-75,0xFFFFFFFF);super.render(c,x,y,d);} }
